/**
 * Glossary of travel, visa, Hajj and Umrah terms used across URAL.
 *
 * Rules for every entry (enforced by `npm run test:glossary`):
 * - a plain definition in English and in Bengali, written by hand;
 * - no fee, price or exchange figure, and no religious ruling. A definition
 *   says what a word means; rules and amounts live in the linked guide and on
 *   the official page, which carry their own dates;
 * - `guide` is the English path of a published URAL page;
 * - `source` is an address already in the official sources registry.
 */
export type GlossaryGroupId = "hajj-umrah" | "visa" | "money" | "flights" | "rights" | "documents";

export interface GlossaryTerm {
  id: string;
  group: GlossaryGroupId;
  en: string;
  bn: string;
  /** Other spellings and names people search for, in either language. */
  aka?: readonly string[];
  defEn: string;
  defBn: string;
  guide?: string;
  source?: string;
}

/** Display order of the groups on the page. */
export const GLOSSARY_GROUPS: readonly { id: GlossaryGroupId; en: string; bn: string }[] = [
  { id: "hajj-umrah", en: "Hajj and Umrah", bn: "হজ ও ওমরাহ" },
  { id: "visa", en: "Visa and entry", bn: "ভিসা ও প্রবেশ" },
  { id: "money", en: "Money and banking", bn: "অর্থ ও ব্যাংকিং" },
  { id: "flights", en: "Flights and airports", bn: "ফ্লাইট ও বিমানবন্দর" },
  { id: "rights", en: "Passenger rights", bn: "যাত্রী অধিকার" },
  { id: "documents", en: "Documents", bn: "কাগজপত্র" },
];

