/** Terms of one group, in alphabetical order of the name in the page language. */
export function glossaryTermsByGroup(group: GlossaryGroupId, locale: "en" | "bn" = "en"): GlossaryTerm[] {
  return GLOSSARY_TERMS.filter((term) => term.group === group).sort((a, b) =>
    a[locale].localeCompare(b[locale], locale, { sensitivity: "base" })
  );
}
